276	
277	          {/* Pending invitations */}
278	          {(pendingInvitations.length > 0 || (isLoading && canManage)) && (
279	            <Card>
280	              <CardHeader className="pb-3">
281	                <div className="flex items-center justify-between">
282	                  <CardTitle className="text-sm font-semibold flex items-center gap-2">
